-- State transitions declared for DeliveryNote: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION inventory.delivery_notes_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'submitted'), ('submitted', 'cancelled'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: delivery_notes.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_delivery_notes__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS delivery_notes_status_transition_check ON inventory.delivery_notes;
CREATE TRIGGER delivery_notes_status_transition_check
    BEFORE UPDATE OF "status" ON inventory.delivery_notes
    FOR EACH ROW EXECUTE FUNCTION inventory.delivery_notes_status_transition_check();
